export const CRYPTO_LIST = [
  { symbol: "BTC", name: "Bitcoin" },
  { symbol: "ETH", name: "Ethereum" },
  { symbol: "USDT", name: "Tether" },
  { symbol: "BNB", name: "BNB" },
  { symbol: "SOL", name: "Solana" },
];

const BASE_PRICES: Record<string, number> = {
  BTC: 65000,
  ETH: 3500,
  USDT: 1.0,
  BNB: 400,
  SOL: 150,
};

const MARKET_CAPS: Record<string, number> = {
  BTC: 1280000000000,
  ETH: 420000000000,
  USDT: 110000000000,
  BNB: 58000000000,
  SOL: 65000000000,
};

const VOLUMES: Record<string, number> = {
  BTC: 35000000000,
  ETH: 18000000000,
  USDT: 85000000000,
  BNB: 2000000000,
  SOL: 5000000000,
};

function getSimulatedPrice(symbol: string): number {
  const base = BASE_PRICES[symbol] || 100;
  const hour = Math.floor(Date.now() / (1000 * 60 * 60));
  const seed = (hour * 1234567 + symbol.charCodeAt(0) * 987) % 10000;
  const variation = (seed / 10000 - 0.5) * 0.06;
  return parseFloat((base * (1 + variation)).toFixed(2));
}

function getSimulatedChange(symbol: string): number {
  const hour = Math.floor(Date.now() / (1000 * 60 * 60 * 24));
  const seed = (hour * 7654321 + symbol.charCodeAt(0) * 123) % 10000;
  const change = (seed / 10000 - 0.5) * 8;
  return parseFloat(change.toFixed(2));
}

export function getCryptoPrices() {
  return CRYPTO_LIST.map((coin) => {
    const price = getSimulatedPrice(coin.symbol);
    const changePercent = getSimulatedChange(coin.symbol);
    const change24h = parseFloat(((price * changePercent) / 100).toFixed(2));
    return {
      symbol: coin.symbol,
      name: coin.name,
      price,
      change24h,
      changePercent24h: changePercent,
      marketCap: MARKET_CAPS[coin.symbol] || 0,
      volume24h: VOLUMES[coin.symbol] || 0,
    };
  });
}

export function getPrice(symbol: string): number {
  return getSimulatedPrice(symbol.toUpperCase());
}
